import pathlib,threading,json,time,base64,gzip,traceback
root5=pathlib.Path('/content/mathvisionkid_corrective_5h_20261024')
prior_controls_thread=globals().get('corrective_controls_thread')
queue_path=root5/'four_controls_queue_status.json'
def _queue_latest_controls():
 try:
  queue_path.write_text(json.dumps({'state':'WAITING_PRIOR_TRANSACTION','queued_unix':time.time()}))
  if prior_controls_thread:prior_controls_thread.join(1800)
  assert not prior_controls_thread or not prior_controls_thread.is_alive(),'Prior transaction still active'
  prior=json.loads((root5/'four_controls_publication_status.json').read_bytes())
  assert prior['state']=='COMPLETE_RAW_VERIFIED','Prior transaction did not complete'
  exec(gzip.decompress(base64.b64decode('')).decode(),globals())
  queue_path.write_text(json.dumps({'state':'LATEST_TRANSACTION_STARTED','at_unix':time.time()}))
 except Exception as e:queue_path.write_text(json.dumps({'state':'ERROR','error':repr(e),'traceback':traceback.format_exc()}))
assert not globals().get('corrective_controls_queue_thread') or not corrective_controls_queue_thread.is_alive()
corrective_controls_queue_thread=threading.Thread(target=_queue_latest_controls,name='MathVisionKidLatestControlsQueue',daemon=True);corrective_controls_queue_thread.start()
print(json.dumps({'latest_context_queued':True,'train_changed':False}))
